export const AVA_NAMES = AVAS.map((a) => a[0]);

const byName = new Map(AVAS.map((a) => [a[0].toLowerCase(), a]));

/** The AVA with exactly this name (any case), with its usual region and states. */
export function avaOf(name: string): { name: string; region: string; states: string[] } | null {
  const a = byName.get(name.trim().toLowerCase());
  return a ? { name: a[0], region: a[1], states: a[2].split(",") } : null;
}
